196	    /**
197	     * Run the simulation from its current state for the given number of steps.
198	     * Stop before the given number of steps if it ceases to be viable.
199	     * @param numSteps The number of steps to run for.
200	     */
201	    public void simulate(int numSteps)
202	    {
203	        playingSimulation = true;
204	        remainingSteps = numSteps;
205	
206	        int backupCounter = 1;
207	        while(playingSimulation){
208	            for(int step = 1; step <= numSteps && view.isViable(field); step++) {
209	                simulateOneStep();
210	                backupCounter++;
211	//            delay(60);   // uncomment this to run more slowly
212	            }
213	            if(!view.isViable(field)){
214	                // System.out.println("STEPS COMPLETED: "+backupCounter);
215	                // uncomment this while optimizing for population stability
216	                Thread.currentThread().interrupt();
217	                if(backupCounter > SimulationInfo.HIGHEST_STEPS){
218	                    // If multiple instances of the simulation are created in the same session (for testing),
219	                    // the fields in SimulationInfo can be used for optimizing the default probabilities
220	                    SimulationInfo.HIGHEST_STEPS = backupCounter;
221	                    SimulationInfo.HIGHEST_STEP_PROBS = this.CREATION_PROBABILITIES;
222	                }
223	                playingSimulation = false;
224	                break;
225	            }
226	        }
227	        remainingSteps = numSteps - backupCounter;
228	    }
