230	    /**
231	     * Run the simulation from its current state for a single step.
232	     * Iterate over the whole field updating the state of each
233	     * organism.
234	     */
235	    public void simulateOneStep()
236	    {
237	        if(!playingSimulation){ return; }
238	        step++;
239	        environment.getTime().incrementTime();
240	        environment.getWeather().checkWeatherChange(step);
241	
242	
243	        // Provide space for newborn animals.
244	        List<Actor> newActors = new ArrayList<>();
245	        // Let all actors act.
246	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
247	            Actor actor = it.next();
248	            if(actor instanceof Animal){
249	               if(((Animal) actor).isAwake(environment)) {
250	                   if(((Animal) actor).isDiseased() && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
251	                       ((Animal) actor).setDead();
252	                   }
253	                   actor.act(newActors, environment);
254	               }
255	            }
256	            else {
257	                actor.act(newActors, environment);
258	            }
259	
260	            if(actor instanceof Plant){
261	                if(step % ((Plant) actor).STEPS_PER_STAGE()==0){
262	                    ((Plant) actor).incrementGrowth();
263	                }
264	            }
265	
266	            if(! actor.isAlive()) {
267	                it.remove();
268	            }
269	
270	
271	
272	        }
273	        actors.addAll(newActors);
274	        plantGrassInPatches();
275	
276	        view.showStatus(step, environment.getWeather().getCurrentWeather().toString(), environment.getTime().getCurrentTimeString(), field);
277	    }
