280	     * Randomly generate grass in free patches on the field, only if it is raining
281	     */
282	    private void plantGrassInPatches(){
283	        // new grass is randomly added in patches
284	        for(Location location:field.getRandomFreePatches(CREATION_PROBABILITIES.get(Grass.class))){
285	            if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class) && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
286	                Grass grass = new Grass(field, location);
287	                actors.add(grass);
288	            }
289	        }
290	    }
