325	    private void registerActorFactories()
326	    {
327	        registerActorFactory(Grass.class, (location, sex) -> new Grass(field, location));
328	        registerActorFactory(Deer.class, (location, sex) -> new Deer(true, field, location, sex));
329	        registerActorFactory(Coyote.class, (location, sex) -> new Coyote(true, field, location, sex));
330	        registerActorFactory(Wolf.class, (location, sex) -> new Wolf(true, field, location, sex));
331	        registerActorFactory(Eagle.class, (location, sex) -> new Eagle(true, field, location, sex));
332	        registerActorFactory(Mouse.class, (location, sex) -> new Mouse(true, field, location, sex));
333	        registerActorFactory(Hunter.class, (location, sex) -> createHunter(location));
334	    }
