341	    private void addInitialActorAt(Location location)
342	    {
343	        Actor actor = createInitialActor(location);
344	        if(actor != null) {
345	            actors.add(actor);
346	        }
347	    }
348	
349	    private Actor createInitialActor(Location location)
350	    {
351	        Animal.Gender sex = Randomizer.getRandomSex();
352	        for(Map.Entry<Class<?>, ActorFactory> entry : actorFactories.entrySet()) {
353	            if(rand.nextDouble() <= getCreationProbability(entry.getKey())) {
354	                return entry.getValue().create(location, sex);
355	            }
356	        }
357	        return null;
358	    }
359	
360	    private double getCreationProbability(Class<?> actorClass)
361	    {
362	        return CREATION_PROBABILITIES.getOrDefault(actorClass, 0.0);
363	    }
364	
365	    private Actor createHunter(Location location)
366	    {
367	        if(hunterCount >= HUNTER_LIMIT) {
368	            return null;
369	        }
370	        hunterCount++;
371	        return new Hunter(field, location, environment);
372	    }
